import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, vec4, mix, time, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, PointLight } = THREE;

  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const hexToVec3 = (hex) => {
    const n = parseInt(hex.replace('#', ''), 16);
    return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
  };

  const [inkR, inkG, inkB] = hexToVec3(colors.ink);
  const [surR, surG, surB] = hexToVec3(colors.surface);
  const accentHexNum = parseInt(colors.accent.replace('#', ''), 16);

  const root = new Group();
  root.name = 'nova-hero-showpiece';

  // --- geometry sizing from atlas region aspect (512x320 = 1.6:1) ---
  const rect = { w: 512, h: 320 };
  const aspect = rect.w / rect.h;
  const height = 3.3; // ~60% of hub frame height (5.5 units)
  const width = height * aspect;

  const planeGeo = new PlaneGeometry(width, height, 1, 1);

  // Placeholder material -- ink solid until texture resolves.
  const material = new MeshBasicNodeMaterial();
  material.transparent = true;
  material.side = THREE.DoubleSide;
  material.opacity = 0;
  material.colorNode = vec4(vec3(inkR, inkG, inkB), 1.0);

  const subject = new Mesh(planeGeo, material);
  subject.name = 'hero-showpiece-plane';
  subject.position.set(0, 0, 0.15);

  // Billboard toward camera every frame (no ctx camera access needed).
  subject.onBeforeRender = function (renderer, scene, camera) {
    this.quaternion.copy(camera.quaternion);
  };

  root.add(subject);

  // --- soft grounding shadow (foreground depth layer, subtle) ---
  const shadowGeo = new PlaneGeometry(width * 1.25, height * 0.55, 1, 1);
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.transparent = true;
  shadowMat.depthWrite = false;
  const sUv = uv();
  const dist = sUv.sub(vec2(0.5, 0.5)).length();
  const shadowAlpha = dist.oneMinus().clamp(0.0, 1.0).pow(2.2).mul(0.45);
  shadowMat.colorNode = vec4(vec3(surR, surG, surB), shadowAlpha);
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.rotation.x = -Math.PI / 2.4;
  shadowMesh.position.set(0, -height * 0.52, -0.3);
  root.add(shadowMesh);

  // --- node-local rim/accent light (opposite key, carries accent hue) ---
  const rimLight = new PointLight(accentHexNum, 0.9, 7, 2);
  rimLight.position.set(-1.4, 0.8, 1.6);
  root.add(rimLight);

  // --- texture load: compose engineered gradient + subtle grain over image ---
  let loadedTexture = null;
  if (ctx.textureLoader && config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        loadedTexture = tex;
        const texColor = texture(tex);
        const gradTop = vec3(inkR, inkG, inkB);
        const gradBottom = vec3(surR, surG, surB);
        const gradient = mix(gradBottom, gradTop, uv().y);

        const grainSeed = uv().x.mul(913.234).add(uv().y.mul(271.746)).add(time.mul(0.05));
        const grain = grainSeed.sin().mul(4375.545).fract().sub(0.5).mul(0.05);

        const blended = mix(gradient, texColor.rgb, 0.92).add(grain);
        material.colorNode = vec4(blended, texColor.a);
        material.needsUpdate = true;
      })
      .catch(() => {
        // keep placeholder ink color on failure
      });
  }

  // --- weighted-settle entrance (no idle motion: static composition per spec) ---
  root.scale.setScalar(0.96);
  const tl = gsap.timeline();
  tl.to(root.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });
  tl.to(
    material,
    {
      opacity: 1,
      duration: 0.7,
      ease: 'power2.out',
      onUpdate: () => {
        material.needsUpdate = true;
      },
    },
    0.05
  );

  // --- apply any configured cinematic primitives (none specified for this node) ---
  const primitiveHandles = [];
  const primitiveList = config.cinematicPrimitives ?? [];
  for (const prim of primitiveList) {
    if (prim && prim.name && ctx.primitives && ctx.primitives[prim.name]) {
      const handle = ctx.primitives[prim.name](root, prim.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    tl.kill();
    for (const h of primitiveHandles) {
      h?.cleanup?.();
    }
    planeGeo.dispose();
    shadowGeo.dispose();
    material.dispose();
    shadowMat.dispose();
    if (loadedTexture) {
      loadedTexture.dispose();
    }
    root.remove(subject);
    root.remove(shadowMesh);
    root.remove(rimLight);
  };

  return root;
}
